def transform(grid):
    """Recolor full-width/full-height separator lines to color 2."""
    if not grid or not grid[0]:
        return grid
    h, w = len(grid), len(grid[0])
    sep = grid[0][0]
    out = [row[:] for row in grid]
    separator_rows = {i for i, row in enumerate(grid) if all(v == sep for v in row)}
    separator_cols = {j for j in range(w) if all(grid[i][j] == sep for i in range(h))}
    for i in range(h):
        for j in range(w):
            if i in separator_rows or j in separator_cols:
                out[i][j] = 2
    return out

